INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("1", "aetheria-os", "AETHERIA OS", "NEOBRUTALISM // SPATIAL COMPUTING", "SPATIAL COMPUTING // 2026", "[\"spatial\",\"systems\"]"::jsonb, "2026", "Spatial Design System, Holographic HUD, Ambient Audio Engine, Micro-Interactions", "Three.js, WebGL 2.0, Web Audio API, GSAP Motion, Shaders", "Aetheria OS represents our exploration into post-screen spatial interaction. Built around an acoustic ambient field, the interface dynamically warps visual density based on cognitive auditory feedback. Every UI primitive responds to gravity vectors with sub-pixel inertia.", "assets/images/Neobrutalist_digital_art_geometr…_20260918114558.jpeg", "assets/images/thumbs/thumb-11.jpeg", true, 0, "AETHERIA OS", "NEOBRUTALISM // SPATIAL", "[\"SPATIAL // 01\",\"THREE.JS SHADER\"]"::jsonb, "Aetheria OS Interface", 0, true, true, false) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("2", "vanguard-kinetic", "VANGUARD KINETIC", "SWISS STYLE // TELEMETRY & AERODYNAMICS", "HYPERCAR TELEMETRY // 2026", "[\"telemetry\",\"identity\"]"::jsonb, "2026", "CAN-Bus Telemetry HUD, Aerodynamic Visualizer, Type Foundry Specimen", "WebGL Real-Time Shaders, Vector Aerodynamics, Custom GLSL", "High-speed aerodynamic telemetry system designed for an electric hypercar concept. The interface translates live wind-tunnel turbulence and tyre temperature telemetry into an intuitive HUD dashboard optimized for 300+ km/h reaction times.", "assets/images/Swiss_style_graphic_design_layout_20260918114558.jpeg", "assets/images/thumbs/thumb-12.jpeg", true, 1, "SWISS KINETIC", "SWISS STYLE // TELEMETRY", "[\"AERO // 02\",\"HUD SYSTEM\"]"::jsonb, "Vanguard Kinetic Telemetry", 1, true, true, false) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("3", "monoform-foundry", "MONOFORM FOUNDRY", "BAUHAUS // VARIABLE TYPE FOUNDRY", "ALGORITHMIC TYPE // 2025", "[\"identity\",\"systems\"]"::jsonb, "2025", "Variable Font Specimen Site, Glyphs Engine, Interactive Type Tester", "Variable Font Axes, CSS Houdini, Kinetic Typography", "Monoform Foundry investigates the intersection between architectural Brutalism and dynamic variable typography. The site generates algorithmic specimens in real time based on scroll velocity and audio frequency inputs.", "assets/images/Bauhaus_geometric_art_composition_20260918114558.jpeg", "assets/images/thumbs/thumb-2.jpeg", true, 2, "BAUHAUS COMPOSITION", "BAUHAUS // VARIABLE TYPE", "[\"TYPE // 03\",\"VARIABLE SPECIMEN\"]"::jsonb, "Monoform Variable Type Foundry", 2, true, true, true) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("4", "lumina-bioclimatic", "LUMINA BIOCLIMATIC", "BRUTALIST ARCHITECTURE // SPATIAL IDENTITY", "SUSTAINABLE ARCH // 2025", "[\"identity\",\"spatial\"]"::jsonb, "2025", "Identity Architecture, Solar Radiation Interactive Map, Spatial Signage", "Three.js Solar Shaders, Parametric Timber Simulation", "A comprehensive brand and digital presence for a carbon-negative pavilion in Scandinavia. The design system incorporates continuous real-time solar tracking with live shadow projections rendered natively in WebGL.", "assets/images/Brutalist_architecture_graphic_20260918114558.jpeg", "assets/images/thumbs/thumb-3.jpeg", true, 3, "BRUTALIST ARCHITECTURE", "BRUTALIST ARCHITECTURE", "[\"ARCH // 04\",\"SOLAR SHADOWS\"]"::jsonb, "Lumina Bioclimatic Pavilion", 3, true, true, true) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("5", "solaria-energy", "SOLARIA ENERGY", "RETRO-GRID // CONTINENTAL ENERGY OS", "CONTINENTAL TELEMETRY // 2026", "[\"systems\",\"telemetry\"]"::jsonb, "2026", "Grid Control OS, Continental Energy Flow Map, Real-time Alerts", "High-frequency WebSocket Data, Canvas 2D, WebGL Shaders", "A planetary telemetry dashboard mapping solar and offshore wind energy distribution across Europe. Employs multi-layer vector canvas pipelines to render over 20,000 live turbine points without frame latency.", "assets/images/Vaporwave_grid_landscape_sunset_20260918114558.jpeg", "assets/images/thumbs/thumb-13.jpeg", true, 4, "VAPORWAVE GRID", "RETRO-GRID // CONTINENTAL OS", "[\"GRID // 05\",\"REALTIME WS STREAM\"]"::jsonb, "Solaria Continental Energy Grid", 4, true, true, true) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
