INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("p1", "brutalist-monolith", "BRUTALIST MONOLITH", "ARCHITECTURAL FORM // 35MM FILM", "ARCHITECTURAL GEOMETRY // 2026", "[\"photography\",\"architecture\",\"analog\"]"::jsonb, "2026", "Monochrome Architectural Study, Museum Print Edition, Spatial Morphology", "Leica M6, Summicron 35mm f/2, Kodak Tri-X 400 Silver Gelatin", "An architectural investigation documenting raw concrete brutalist structures and stark geometric cantilever forms. Shot exclusively on high-contrast 35mm black-and-white film to emphasize tactile texture and harsh sunlight shadow planes.", "assets/images/photo-1-architecture.jpg", "assets/images/photo-1-architecture.jpg", false, NULL, NULL, NULL, "[\"ARCH // 35MM\",\"LEICA // F/8\"]"::jsonb, "Brutalist Monolith Architectural Photography", 13, true, true, true) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("p2", "avant-garde-shadow", "AVANT-GARDE SHADOW", "HAUTE COUTURE // EDITORIAL PORTRAITURE", "HAUTE COUTURE SILHOUETTE // 2026", "[\"photography\",\"editorial\"]"::jsonb, "2026", "Editorial Lookbook, Sculptural Fashion Direction, High-Key Chiaroscuro", "Medium Format Digital, Broncolor Para Lighting, Monochromatic Grading", "High-concept fashion editorial centered on architectural silhouettes and extreme chiaroscuro. The series examines the boundary between garment structure and monolithic spatial form with precision studio lighting.", "assets/images/photo-2-portrait.jpg", "assets/images/photo-2-portrait.jpg", false, NULL, NULL, NULL, "[\"EDITORIAL // 02\",\"CHIAROSCURO\"]"::jsonb, "Avant-Garde Shadow & Form Editorial Portrait", 14, false, true, true) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("p3", "volcanic-seascape", "VOLCANIC SEASCAPE", "ANALOG LANDSCAPE // MEDIUM FORMAT", "MEDIUM FORMAT ANALOG // 2025", "[\"photography\",\"analog\"]"::jsonb, "2025", "Fine Art Exhibition Portfolio, Archival Pigment Prints, Analog Field Study", "Hasselblad 500C/M, Carl Zeiss 80mm f/2.8, Ilford HP5+ 120 Film", "Documenting the stark coastal geology and basalt monoliths of Nordic volcanic beaches. Captured on medium format roll film under dense sea mist and low Arctic sun, evoking timeless primeval isolation.", "assets/images/photo-3-landscape.jpg", "assets/images/photo-3-landscape.jpg", false, NULL, NULL, NULL, "[\"ANALOG // HASSELBLAD\",\"NORDIC MONOLITH\"]"::jsonb, "Volcanic Seascape Medium Format Analog", 15, true, true, true) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("v1", "kinetic-hypercar-drift", "KINETIC HYPERCAR DRIFT", "DIRECTOR OF PHOTOGRAPHY // 2026", "DIRECTOR OF PHOTOGRAPHY // 2026", "[\"videography\",\"cinematic\",\"commercial\"]"::jsonb, "2026", "4K DCI Cinema Master, High-Speed Pursuit Pipeline, Anamorphic Lens Flare Suite", "ARRI Alexa Mini LF, Atlas Orion 2x Anamorphic, Gyro-Stabilized Pursuit Rig", "High-octane nocturnal cinema spot tracking an electric hypercar through rain-slicked Tokyo highways. Features horizontal blue anamorphic flares, visceral wet-surface light reflections, and authentic motion-picture texture.", "assets/images/video-1-hypercar.jpg", "assets/images/video-1-hypercar.jpg", false, NULL, NULL, NULL, "[\"REC // 24FPS\",\"4K DCI ANAMORPHIC\"]"::jsonb, "Kinetic Hypercar Drift Anamorphic Frame", 16, true, false, true) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("v2", "brutalist-atrium-brand-film", "BRUTALIST ATRIUM // BRAND FILM", "COMMERCIAL DIRECTION // 2025", "COMMERCIAL DIRECTION // 2025", "[\"videography\",\"cinematic\",\"commercial\"]"::jsonb, "2025", "Commercial Direction, Volumetric Lighting Design, Soundscape Synthesis", "RED V-Raptor 8K, Master Primes, Custom LUT Color Architecture", "A moody commercial brand film set in a towering brutalist concrete atrium. Volumetric sun beams cut through morning atmospheric haze to create an ethereal, monumental sense of scale and architectural poetry.", "assets/images/video-2-fashion.jpg", "assets/images/video-2-fashion.jpg", false, NULL, NULL, NULL, "[\"ARRI ALEXA 65\",\"VOLUMETRIC LIGHT\"]"::jsonb, "Brutalist Atrium Commercial Brand Film", 17, true, true, true) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
INSERT INTO public.projects (id, slug, title, meta, subtitle, categories, year, deliverables, tech, description, image, thumb, featured, hero_slot, hero_title, hero_tag, badges, alt, sort_order, show_photo, show_video, show_graphic) VALUES ("v3", "cybernetic-stage-echo", "CYBERNETIC STAGE ECHO", "EXPERIMENTAL LIVE VISUALS // 2026", "EXPERIMENTAL LIVE VISUALS // 2026", "[\"videography\",\"experimental\"]"::jsonb, "2026", "Live Stage Visual Engineering, Laser Synchronizer, Real-Time Audio Reactive Shaders", "Kinetix Robotic Rig, TouchDesigner 60FPS Pipeline, Custom GLSL Laser Nodes", "An immersive live performance visual installation fusing kinetic robotic LED arms, synchronized volumetric laser arrays, and real-time audio reactive shader feeds for a futuristic concert experience.", "assets/images/video-3-stage.jpg", "assets/images/video-3-stage.jpg", false, NULL, NULL, NULL, "[\"35MM MOTION\",\"GLSL LIVE LASERS\"]"::jsonb, "Cybernetic Stage Echo Live Visuals", 18, true, true, true) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, image = EXCLUDED.image, categories = EXCLUDED.categories, featured = EXCLUDED.featured;
