INSERT INTO public.site (key, value) VALUES ("meta", "{\"title\":\"AETHER / KINETIC STUDIO — Brand, Spatial & Generative Engineering\",\"description\":\"Aether is an independent creative technology and digital design studio engineering tactile digital realities, spatial interfaces, and kinetic typography.\"}"::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO public.site (key, value) VALUES ("hero", "{\"tagline\":\"Brand, Spatial & Generative Engineering\"}"::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO public.site (key, value) VALUES ("ticker", "[\"SPATIAL COMPUTING\",\"GENERATIVE SHADERS\",\"HYPERCAR TELEMETRY\",\"VARIABLE TYPE FOUNDRY\",\"BIOCLIMATIC IDENTITY\",\"CONTINENTAL GRID OS\"]"::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO public.site (key, value) VALUES ("about", "{\"label\":\"STUDIO // ABOUT ME\",\"heading\":\"ENGINEERING DIGITAL REALITIES.\",\"bio\":\"[BIO TEXT HERE]\",\"photo\":\"assets/images/profile.jpg\",\"photoAlt\":\"Profile Portrait\",\"photoBadge\":\"STUDIO LEAD // 2026\",\"caption\":\"DISCIPLINE: BRAND, SPATIAL & GENERATIVE\",\"skillsLabel\":\"ARSENAL // SKILLS & TOOLS\",\"skills\":[\"[SKILL 1]\",\"[SKILL 2]\",\"[SKILL 3]\",\"[SKILL 4]\",\"[SKILL 5]\",\"[SKILL 6]\",\"[SKILL 7]\",\"[SKILL 8]\"],\"pillarsLabel\":\"STUDIO ETHOS & TECHNICAL PILLARS\",\"pillars\":[{\"num\":\"01 // VISCERAL SHADERS\",\"title\":\"Kinetic Physics\",\"desc\":\"Sub-pixel inertia, wave displacement, and volumetric shaders calculated in real time on the GPU.\"},{\"num\":\"02 // ARCHITECTURAL TYPE\",\"title\":\"Variable Rhythm\",\"desc\":\"Contemporary grotesques paired with technical mono grids to create unmistakable editorial hierarchies.\"},{\"num\":\"03 // HIGH-SPEED TELEMETRY\",\"title\":\"Instantaneous Latency\",\"desc\":\"Optimized zero-jank frame cycles matching 120Hz ProMotion displays with zero unnecessary weight.\"},{\"num\":\"04 // BESPOKE ENGINEERING\",\"title\":\"Autonomous Code\",\"desc\":\"Zero generic component templates. Every transition curve and visual asset tailored to the project DNA.\"}]}"::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO public.site (key, value) VALUES ("works", "{\"label\":\"SELECTED WORKS // 2024 — 2026\",\"heading\":\"ENGINEERED EXPERIENCES\"}"::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO public.site (key, value) VALUES ("contact", "{\"label\":\"START A COLLABORATION\",\"heading\":\"HAVE A VISION IN MIND?\",\"desc\":\"We are currently scheduling bespoke digital identities, spatial design systems, and WebGL experiences for Q3/Q4.\",\"email\":\"studio@aether-kinetic.com\",\"mailtoSubject\":\"Project Inquiry\",\"copyright\":\"© 2026 AETHER KINETIC STUDIO. ALL RIGHTS RESERVED.\",\"socials\":[{\"label\":\"GITHUB\",\"url\":\"https://github.com\"},{\"label\":\"BEHANCE\",\"url\":\"https://behance.net\"},{\"label\":\"TWITTER / X\",\"url\":\"https://twitter.com\"},{\"label\":\"INSTAGRAM\",\"url\":\"https://instagram.com\"}]}"::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
